CREATE TABLE IF NOT EXISTS estaciones(id INTEGER PRIMARY KEY,nombre TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS usuarios(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password TEXT NOT NULL,rol TEXT NOT NULL CHECK(rol IN ('admin','eas')),estacion_id INTEGER REFERENCES estaciones(id),CHECK(rol='admin' OR estacion_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS actividades(id INTEGER PRIMARY KEY,nombre TEXT NOT NULL UNIQUE,estado INTEGER NOT NULL DEFAULT 1 CHECK(estado IN(0,1)),creado TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,modificado TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS moviles(id INTEGER PRIMARY KEY,placa TEXT NOT NULL UNIQUE,numero TEXT NOT NULL UNIQUE,kilometraje REAL NOT NULL DEFAULT 0 CHECK(kilometraje>=0),combustible TEXT NOT NULL CHECK(combustible IN('Lleno','3/4','1/2','1/4','Reserva')),novedades TEXT NOT NULL DEFAULT '',estacion_id INTEGER NOT NULL REFERENCES estaciones(id));
CREATE TABLE IF NOT EXISTS registros(id INTEGER PRIMARY KEY,fecha TEXT NOT NULL,movil_id INTEGER NOT NULL REFERENCES moviles(id),actividad_id INTEGER NOT NULL REFERENCES actividades(id) ON DELETE RESTRICT,actividad_nombre TEXT NOT NULL,estacion_id INTEGER NOT NULL REFERENCES estaciones(id),detalle TEXT NOT NULL DEFAULT '',usuario_id INTEGER NOT NULL REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS migraciones(nombre TEXT PRIMARY KEY,aplicado TEXT DEFAULT CURRENT_TIMESTAMP);
